import Phaser from 'phaser';

import { COLORS } from '@/config';

/** Slice size of the 96×96 `ui_window` texture (docs/GAME_DESIGN.md §11.1). */
const SLICE = 32;

/**
 * Menu/dialog window frame (docs/GAME_DESIGN.md §11.1). On WebGL it stretches the
 * `ui_window` 9-slice texture (UI-01, generated by scripts/art); the Canvas renderer
 * has no NineSlice, so it draws the same look with Graphics instead.
 */
export class Window extends Phaser.GameObjects.Container {
  private readonly frame: Phaser.GameObjects.Graphics | undefined;
  private readonly slice: Phaser.GameObjects.NineSlice | undefined;
  private frameWidth: number;
  private frameHeight: number;

  constructor(scene: Phaser.Scene, x: number, y: number, width: number, height: number) {
    super(scene, x, y);
    this.frameWidth = width;
    this.frameHeight = height;
    const webgl = scene.sys.game.renderer.type === Phaser.WEBGL;
    if (webgl && scene.textures.exists('ui_window')) {
      this.slice = scene.add
        .nineslice(0, 0, 'ui_window', undefined, width, height, SLICE, SLICE, SLICE, SLICE)
        .setOrigin(0);
      this.add(this.slice);
    } else {
      this.frame = scene.add.graphics();
      this.add(this.frame);
      this.redraw();
    }
    scene.add.existing(this);
  }

  resize(width: number, height: number): void {
    this.frameWidth = width;
    this.frameHeight = height;
    if (this.slice) this.slice.setSize(width, height);
    else this.redraw();
  }

  private redraw(): void {
    const g = this.frame;
    if (!g) return;
    g.clear();
    g.fillStyle(COLORS.deepSea, 0.85);
    g.fillRoundedRect(0, 0, this.frameWidth, this.frameHeight, 6);
    g.lineStyle(2, 0xc9a66b, 1);
    g.strokeRoundedRect(1, 1, this.frameWidth - 2, this.frameHeight - 2, 6);
    g.lineStyle(1, 0xf4f1ea, 0.35);
    g.strokeRoundedRect(4, 4, this.frameWidth - 8, this.frameHeight - 8, 4);
  }
}
